<?php require __DIR__.'/common.php';$u=monitor_user();$d=db();$rows=monitor_rows($d,$u);$d->close();head('Usuń monitorowaną usługę');echo '<form method="post" action="kasuj2.php" class="card p-4"><input type="hidden" name="csrf" value="'.h(monitor_csrf()).'"><label for="service" class="form-label">Host i port do usunięcia</label><select class="form-select mb-3" name="id" id="service" required>';foreach($rows as $r)echo '<option value="'.(int)$r['id'].'">'.h($r['host']).':'.(int)$r['port'].' — '.h($r['username']).'</option>';echo '</select><button class="btn btn-danger" '.(!$rows?'disabled':'').'>Usuń wybraną usługę</button></form><a href="monitor.php">Powrót do monitorowania</a>';foot();
